from __future__ import annotations

import logging
from dataclasses import dataclass, field
from typing import Dict, List, Optional, Sequence, Tuple, Union

import numpy as np
import pandas as pd
import ruptures as rpt

# Configure module-level logger
logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


# ---------------------------------------------------------------------------
# Configuration Dataclasses
# ---------------------------------------------------------------------------

@dataclass(frozen=True)
class RollingWindowConfig:
    """Configuration for rolling statistics computation.

    Attributes:
        window_sizes: List of window sizes (in observations) for rolling stats.
        min_periods: Minimum observations required per window (defaults to window size).
        include_zscore: Whether to compute rolling z-scores.
        include_rate_of_change: Whether to compute rolling rate-of-change.
        zscore_threshold: Threshold for flagging anomalous z-scores.
    """
    window_sizes: Tuple[int, ...] = (5, 15, 30)
    min_periods: Optional[int] = None
    include_zscore: bool = True
    include_rate_of_change: bool = True
    zscore_threshold: float = 3.0

    def __post_init__(self) -> None:
        if not self.window_sizes:
            raise ValueError("window_sizes must contain at least one value")
        if any(w < 2 for w in self.window_sizes):
            raise ValueError("window_sizes must be >= 2")
        if self.zscore_threshold <= 0:
            raise ValueError("zscore_threshold must be positive")


@dataclass(frozen=True)
class ChangePointConfig:
    """Configuration for change-point detection.

    Attributes:
        model: Ruptures model type ('rbf', 'linear', 'l2', etc.).
        pen_factor: Penalty multiplier for PELT (higher = fewer change-points).
        min_segment_len: Minimum segment length between change-points.
        jump: Step size for the search grid.
    """
    model: str = "rbf"
    pen_factor: float = 3.0
    min_segment_len: int = 5
    jump: int = 1

    def __post_init__(self) -> None:
        valid_models = {"rbf", "linear", "l2", "ar", "normal"}
        if self.model not in valid_models:
            raise ValueError(f"model must be one of {valid_models}")
        if self.pen_factor <= 0:
            raise ValueError("pen_factor must be positive")
        if self.min_segment_len < 1:
            raise ValueError("min_segment_len must be >= 1")
        if self.jump < 1:
            raise ValueError("jump must be >= 1")


# ---------------------------------------------------------------------------
# Feature Engineering Module
# ---------------------------------------------------------------------------

class FeatureEngine:
    """
    Production-grade feature engineering for swarm performance telemetry.

    This class provides:
        1. Rolling statistics (mean, std, min, max, median, quantiles).
        2. Rolling z-scores for anomaly detection.
        3. Rate-of-change (first derivative) estimation.
        4. Change-point detection using the PELT algorithm.

    The module is designed to be stateless per-call (thread-safe) and
    operates on pandas DataFrames with a datetime index.
    """

    def __init__(
        self,
        rolling_config: Optional[RollingWindowConfig] = None,
        change_point_config: Optional[ChangePointConfig] = None,
    ) -> None:
        """
        Initialize the FeatureEngine with configuration.

        Args:
            rolling_config: Configuration for rolling statistics.
            change_point_config: Configuration for change-point detection.

        Raises:
            ValueError: If configuration is invalid.
        """
        self.rolling_config = rolling_config or RollingWindowConfig()
        self.cp_config = change_point_config or ChangePointConfig()
        logger.info(
            "FeatureEngine initialized with rolling_config=%s, cp_config=%s",
            self.rolling_config,
            self.cp_config,
        )

    # ------------------------------------------------------------------
    # Public API
    # ------------------------------------------------------------------

    def transform(
        self,
        df: pd.DataFrame,
        value_columns: Optional[List[str]] = None,
    ) -> pd.DataFrame:
        """
        Compute all features for the given telemetry DataFrame.

        Args:
            df: Input DataFrame with a datetime index and numeric columns.
            value_columns: Columns to process. If None, all numeric columns are used.

        Returns:
            DataFrame with original columns plus engineered features.

        Raises:
            ValueError: If input is empty or lacks numeric columns.
        """
        self._validate_input(df)

        # Determine columns to process
        if value_columns is None:
            value_columns = df.select_dtypes(include=[np.number]).columns.tolist()
        if not value_columns:
            raise ValueError("No numeric columns available for feature engineering")

        # Work on a copy to avoid mutating the caller's data
        result = df.copy()

        for col in value_columns:
            logger.debug("Engineering features for column: %s", col)
            series = df[col]

            # 1. Rolling statistics
            result = self._add_rolling_statistics(result, series, col)

            # 2. Rolling z-scores
            if self.rolling_config.include_zscore:
                result = self._add_rolling_zscore(result, series, col)

            # 3. Rate of change
            if self.rolling_config.include_rate_of_change:
                result = self._add_rate_of_change(result, series, col)

            # 4. Change-point detection (per column, returns flags)
            result = self._add_change_point_flags(result, series, col)

        # Add global change-point flags (multi-column consensus)
        result = self._add_global_change_point_flags(result, value_columns)

        return result

    # ------------------------------------------------------------------
    # Rolling Statistics
    # ------------------------------------------------------------------

    def _add_rolling_statistics(
        self,
        result: pd.DataFrame,
        series: pd.Series,
        col: str,
    ) -> pd.DataFrame:
        """
        Add rolling mean, std, min, max, median, and quantiles.

        Args:
            result: Output DataFrame being constructed.
            series: Input series for the column.
            col: Column name prefix.

        Returns:
            Updated DataFrame with rolling features.
        """
        min_periods = self.rolling_config.min_periods

        for window in self.rolling_config.window_sizes:
            # Use window size as min_periods if not specified
            effective_min_periods = min_periods or window

            # Rolling mean and standard deviation
            result[f"{col}_roll_mean_{window}"] = (
                series.rolling(window=window, min_periods=effective_min_periods).mean()
            )
            result[f"{col}_roll_std_{window}"] = (
                series.rolling(window=window, min_periods=effective_min_periods).std()
            )

            # Rolling min/max/median
            result[f"{col}_roll_min_{window}"] = (
                series.rolling(window=window, min_periods=effective_min_periods).min()
            )
            result[f"{col}_roll_max_{window}"] = (
                series.rolling(window=window, min_periods=effective_min_periods).max()
            )
            result[f"{col}_roll_median_{window}"] = (
                series.rolling(window=window, min_periods=effective_min_periods).median()
            )

            # Rolling quantiles (25th and 75th percentiles)
            result[f"{col}_roll_q25_{window}"] = (
                series.rolling(window=window, min_periods=effective_min_periods)
                .quantile(0.25)
            )
            result[f"{col}_roll_q75_{window}"] = (
                series.rolling(window=window, min_periods=effective_min_periods)
                .quantile(0.75)
            )

            # Rolling interquartile range (robust spread measure)
            result[f"{col}_roll_iqr_{window}"] = (
                result[f"{col}_roll_q75_{window}"]
                - result[f"{col}_roll_q25_{window}"]
            )

        return result

    def _add_rolling_zscore(
        self,
        result: pd.DataFrame,
        series: pd.Series,
        col: str,
    ) -> pd.DataFrame:
        """
        Add rolling z-scores and anomaly flags.

        Args:
            result: Output DataFrame being constructed.
            series: Input series for the column.
            col: Column name prefix.

        Returns:
            Updated DataFrame with z-score features.
        """
        min_periods = self.rolling_config.min_periods

        for window in self.rolling_config.window_sizes:
            effective_min_periods = min_periods or window

            roll_mean = series.rolling(window=window, min_periods=effective_min_periods).mean()
            roll_std = series.rolling(window=window, min_periods=effective_min_periods).std()

            # Avoid division by zero: replace zero std with NaN
            safe_std = roll_std.replace(0, np.nan)
            zscore = (series - roll_mean) / safe_std

            result[f"{col}_zscore_{window}"] = zscore
            result[f"{col}_anomaly_{window}"] = (
                zscore.abs() > self.rolling_config.zscore_threshold
            ).astype(int)

        return result

    def _add_rate_of_change(
        self,
        result: pd.DataFrame,
        series: pd.Series,
        col: str,
    ) -> pd.DataFrame:
        """
        Add rate-of-change (first derivative) features.

        Args:
            result: Output DataFrame being constructed.
            series: Input series for the column.
            col: Column name prefix.

        Returns:
            Updated DataFrame with rate-of-change features.
        """
        # Simple first difference
        result[f"{col}_roc_1"] = series.diff()

        # Normalized rate of change (percentage change)
        result[f"{col}_roc_pct"] = series.pct_change() * 100.0

        # Smoothed rate of change (centered rolling mean of diff)
        for window in self.rolling_config.window_sizes:
            result[f"{col}_roc_smooth_{window}"] = (
                result[f"{col}_roc_1"]
                .rolling(window=window, center=True, min_periods=1)
                .mean()
            )

        return result

    # ------------------------------------------------------------------
    # Change-Point Detection
    # ------------------------------------------------------------------

    def _add_change_point_flags(
        self,
        result: pd.DataFrame,
        series: pd.Series,
        col: str,
    ) -> pd.DataFrame:
        """
        Detect change-points in the series and add flag columns.

        Args:
            result: Output DataFrame being constructed.
            series: Input series for the column.
            col: Column name prefix.

        Returns:
            Updated DataFrame with change-point flags.
        """
        # Drop NaN values for change-point detection
        clean_series = series.dropna()
        if len(clean_series) < self.cp_config.min_segment_len * 2:
            logger.warning(
                "Series %s too short for change-point detection (%d points)",
                col,
                len(clean_series),
            )
            result[f"{col}_cp_flag"] = 0
            result[f"{col}_cp_score"] = 0.0
            return result

        # Prepare signal as numpy array (2D for ruptures)
        signal = clean_series.values.reshape(-1, 1)

        # Fit PELT model
        try:
            algo = rpt.Pelt(
                model=self.cp_config.model,
                min_size=self.cp_config.min_segment_len,
                jump=self.cp_config.jump,
            ).fit(signal)

            # Compute penalty based on signal length and variance
            penalty = self._compute_penalty(signal)
            change_points = algo.predict(pen=penalty)

            # Convert change-point indices to boolean flags aligned with original index
            cp_indices = set(change_points[:-1])  # Exclude last point (end of series)
            cp_flags = pd.Series(0, index=series.index, dtype=int)

            # Map clean_series positions back to original index
            clean_positions = clean_series.index
            for idx in cp_indices:
                if idx < len(clean_positions):
                    cp_flags.loc[clean_positions[idx]] = 1

            result[f"{col}_cp_flag"] = cp_flags

            # Compute a change-point score (distance from nearest change-point)
            result[f"{col}_cp_score"] = self._compute_cp_scores(
                series.index, clean_positions, cp_indices
            )

        except Exception as e:
            logger.error("Change-point detection failed for %s: %s", col, e)
            result[f"{col}_cp_flag"] = 0
            result[f"{col}_cp_score"] = 0.0

        return result

    def _compute_penalty(self, signal: np.ndarray) -> float:
        """
        Compute an adaptive penalty for PELT based on signal characteristics.

        Args:
            signal: 2D numpy array of shape (n_samples, n_features).

        Returns:
            Penalty value for PELT.
        """
        # Base penalty scaled by signal variance and length
        variance = np.var(signal, axis=0).mean()
        n = len(signal)
        # Heuristic: penalty scales with log(n) * variance * pen_factor
        penalty = self.cp_config.pen_factor * variance * np.log(n)
        # Ensure minimum penalty to avoid over-segmentation
        return max(penalty, 1e-6)

    def _compute_cp_scores(
        self,
        original_index: pd.Index,
        clean_positions: pd.Index,
        cp_indices: set,
    ) -> pd.Series:
        """
        Compute a continuous score representing proximity to change-points.

        Args:
            original_index: Full index of the original series.
            clean_positions: Index of the cleaned (non-NaN) series.
            cp_indices: Set of change-point indices in clean series coordinates.

        Returns:
            Series of scores (0 = far from change-point, 1 = at change-point).
        """
        # Build an array of change-point positions in original index space
        cp_positions = []
        for idx in cp_indices:
            if idx < len(clean_positions):
                cp_positions.append(clean_positions[idx])

        if not cp_positions:
            return pd.Series(0.0, index=original_index)

        # Compute distance to nearest change-point for each original index
        cp_positions_np = np.array([p.value for p in cp_positions])  # Timestamp values
        original_values = np.array([p.value for p in original_index])

        # Vectorized distance computation
        distances = np.min(
            np.abs(original_values[:, None] - cp_positions_np[None, :]), axis=1
        )

        # Convert distance to score using exponential decay
        # Score = exp(-distance / scale), where scale is median distance
        scale = np.median(distances) if len(distances) > 0 else 1.0
        scale = max(scale, 1e-6)  # Avoid division by zero
        scores = np.exp(-distances / scale)

        return pd.Series(scores, index=original_index)

    def _add_global_change_point_flags(
        self,
        result: pd.DataFrame,
        value_columns: List[str],
    ) -> pd.DataFrame:
        """
        Add global change-point flags based on consensus across columns.

        Args:
            result: Output DataFrame being constructed.
            value_columns: List of columns used for feature engineering.

        Returns:
            Updated DataFrame with global change-point flags.
        """
        # Collect all per-column change-point flag columns
        cp_flag_cols = [f"{col}_cp_flag" for col in value_columns if f"{col}_cp_flag" in result.columns]

        if not cp_flag_cols:
            result["global_cp_flag"] = 0
            result["global_cp_consensus"] = 0.0
            return result

        # Sum of flags across columns
        cp_sum = result[cp_flag_cols].sum(axis=1)

        # Global flag: at least one column detected a change-point
        result["global_cp_flag"] = (cp_sum > 0).astype(int)

        # Consensus score: fraction of columns detecting a change-point
        result["global_cp_consensus"] = cp_sum / len(cp_flag_cols)

        return result

    # ------------------------------------------------------------------
    # Validation Helpers
    # ------------------------------------------------------------------

    @staticmethod
    def _validate_input(df: pd.DataFrame) -> None:
        """
        Validate the input DataFrame.

        Args:
            df: Input DataFrame.

        Raises:
            ValueError: If the DataFrame is empty or has no datetime index.
        """
        if df.empty:
            raise ValueError("Input DataFrame is empty")
        if not isinstance(df.index, pd.DatetimeIndex):
            raise ValueError("Input DataFrame must have a DatetimeIndex")


# ---------------------------------------------------------------------------
# Usage Example
# ---------------------------------------------------------------------------

def demo() -> None:
    """
    Demonstrate the FeatureEngine on synthetic swarm telemetry data.
    """
    # Generate synthetic telemetry with a regime shift
    np.random.seed(42)
    n = 500
    timestamps = pd.date_range("2026-01-01", periods=n, freq="5min")

    # Base signal with a change-point at t=250
    base = np.concatenate([
        np.random.normal(50, 5, 250),
        np.random.normal(80, 8, 250),
    ])

    # Add a secondary correlated signal
    secondary = base * 0.7 + np.random.normal(0, 3, n)

    df = pd.DataFrame(
        {
            "cpu_usage": base,
            "memory_usage": secondary,
            "network_io": np.random.normal(100, 20, n),
        },
        index=timestamps,
    )

    # Initialize feature engine
    engine = FeatureEngine(
        rolling_config=RollingWindowConfig(
            window_sizes=(5, 15, 30),
            include_zscore=True,
            include_rate_of_change=True,
        ),
        change_point_config=ChangePointConfig(
            model="rbf",
            pen_factor=3.0,
            min_segment_len=5,
            jump=1,
        ),
    )

    # Transform
    features = engine.transform(df)

    # Print summary
    print(f"Original shape: {df.shape}")
    print(f"Feature shape: {features.shape}")
    print("\nNew feature columns:")
    new_cols = [c for c in features.columns if c not in df.columns]
    for col in new_cols:
        print(f"  {col}")

    # Show change-point detection results
    print("\nChange-point flags (first 10):")
    print(features[["cpu_usage_cp_flag", "global_cp_flag"]].head(10))

    # Verify change-point was detected around index 250
    cp_detected = features["cpu_usage_cp_flag"].iloc[240:260]
    print("\nChange-point detection around t=250:")
    print(cp_detected[cp_detected == 1].index[:5])


if __name__ == "__main__":
    logging.basicConfig(level=logging.INFO)
    demo()